insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-01adf088ea69', 'botany-cell-the-unit-of-life', 'botany', 'The structure of ATP synthase in the plasma membranes of bacteria is nearly identical to that in the mitochondria and chloroplasts of eukaryotic cells. This similarity best supports which of the following hypotheses?', '["Eukaryotic and prokaryotic cells share a common ancestor.","Mitochondria are derived from ancient aerobic bacteria, and chloroplasts are derived from ancient photosynthetic bacteria.","The similarity of ATP synthase in bacteria, mitochondria, and chloroplasts is an example of convergent evolution.","Mitochondria and chloroplasts escaped from eukaryotic cells and formed aerobic and photosynthetic prokaryotes."]'::jsonb, 1, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
