insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-316f439cc0d1', 'zoology-genetics', 'zoology', 'A proficient engineer can easily design skeletal structures that are more functional than those currently found in the forelimbs of such diverse mammals as horses, whales, and bats. That the actual forelimbs of these mammals do not seem to be optimally arranged is because', '["natural selection has not had sufficient time to create the optimal design in each case, but will do so given enough time.","natural selection operates in ways that are beyond the capability of the human mind to comprehend.","in many cases, phenotype is not merely determined by genotype, but by the environment as well.","natural selection is generally limited to modifying structures that were present in previous generations and in previous species."]'::jsonb, 3, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
