insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-53ef576d30ab', 'botany-photosynthesis-in-higher-plants', 'botany', 'Which of the following is the best explanation for why net primary productivity in terrestrial ecosystems tends to increase toward the tropics?', '["The higher species diversity in the tropics tends to increase plant growth.","There are lower metabolic costs to plant growth in the tropics.","The availability of water and warm temperatures in the tropics fosters photosynthesis.","The tropics have more predators that minimize herbivory."]'::jsonb, 2, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
