insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-555e6879657c', 'botany-molecular-basis-of-inheritance', 'botany', 'A gradual drop in the water level of a large lake divided it into three smaller lakes. The division separated a single population of fish into three smaller, isolated populations. After many generations it was determined that the three populations of fish had become three separate species. Which of the following is most likely correct about the three species?', '["There are differences in the nucleotide sequences of certain gene alleles among the species.","There are differences in the amino acid specified by each codon among the species.","There are differences in the type of cleavage that produces the first blastomeres among the species.","There are differences in the composition of ribosomes among the species."]'::jsonb, 0, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
