insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-7780de795cbb', 'botany-internal-organisation-of-plants', 'botany', 'A stem-boring beetle has laid its eggs in the center of a 5-year-old wood twig, and the eggs have matured into larvae. In proper order (inside to outside), what tissues and tissue regions would the larvae encounter as they eat their way toward the outside of the twig? (For simplicity, assume that the epidermis has already fallen off completely.)', '["Pith; primary xylem; secondary xylem; vascular cambium; primary phloem; secondary phloem; cortex","Pith; secondary xylem; primary xylem; vascular cambium; secondary phloem; primary phloem; cortex","Pith; secondary xylem; primary xylem; vascular cambium; primary phloem; secondary phloem; cortex","Pith; primary xylem; secondary xylem; vascular cambium; secondary phloem; primary phloem; cortex"]'::jsonb, 3, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
