insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-7e094c711127', 'zoology-body-fluids-and-circulation', 'zoology', 'A child with type A B blood inherits an IA allele from one parent and an IB allele from the other. The child will carry both A and B glycoproteins on the surface of all red blood cells. This pattern of expression is referred to as', '["codominance","epistasis","polygenic","linkage"]'::jsonb, 2, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
