insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-7fdce4799d21', 'botany-cell-the-unit-of-life', 'botany', 'When the first tiny prokaryotic cell took up residence inside a larger prokaryotic cell, it heralded the advent of the eukaryotic cell and led to an explosion of new life on Earth. Since then, most cells on Earth have internal organelles. Which of the following best summarizes an advantage of having internal membranes and organelles?', '["DNA can reproduce more efficiently.","Even though prokaryotes do not have mitochondria, they contain structures that carry out the same function.","Organelles separate specific reactions in the cell and increase metabolic efficiency.","Compartmentalization enables prokaryotes to reproduce more quickly."]'::jsonb, 2, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
