insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-8132c5f7a51c', 'zoology-genetics', 'zoology', 'In garden peas, the allele for tall plants (D) is completely dominant to the allele for dwarf plants (d) and the allele for violet flower color (W) is completely dominant to the allele for white flower color (w). In a cross between a tall violet plant, with the genotype DDWw, and a dwarf white plant, what phenotypic ratio of the progeny would be expected from this cross?', '["All tall violet","1 tall violet: 1 dwarf violet","1 tall violet: 1 tall white: 1 dwarf violet: 1 dwarf white","1 tall violet: 1 tall white"]'::jsonb, 3, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
