insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-8438fcdf7b53', 'botany-enzymes', 'botany', 'The endocrine system maintains homeostasis using many feedback mechanisms. Which of the following is an example of positive feedback?', '["Infant suckling causes a mother''s brain to release oxytocin, which in turn stimulates milk production.","An enzyme is allosterically inhibited by the product of the reaction it catalyzes.","When ATP is abundant the rate of glycolysis decreases.","When blood sugar levels decrease to normal after a meal, insulin is no longer secreted."]'::jsonb, 0, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
