insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-biology-8611b89958ed', 'botany-respiration-in-plants', 'botany', 'The end product of the alcohol fermentation pathway is the alcohol ethanol. A considerable amount of energy still remains in ethanol, yet ethanol is a waste product for the yeast cells that produce it. What, then, is the purpose of fermentation?', '["Fermentation provides CO2 for photosynthesis.","Fermentation provides CO2 for cellular respiration.","Yeast cells excrete ethanol in order to provide a defense against invading bacteria.","Fermentation replenishes the NAD+ necessary for glycolysis to continue."]'::jsonb, 3, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
