insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-chemistry-64834bc2e7e0', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'The first ionization energy for a neutral atom of chlorine is 1.25 MJ/mol and the first ionization energy for a neutral atom of argon is 1.52 MJ/mol. How would the first ionization energy value for a neutral atom of potassum compare to those values?', '["It would be greater than both because potassium carries a greater nuclear charge then either chlorine or argon.","It would be greater than both because the size of a potassium atom is smaller than an atom of either chlorine or argon.","It would be less than both because there are more electrons in potassium, meaning they repel each other more effectively and less energy is needed to remove one.","It would be less than both because a valence electron of potassium is farther from the nucleus than one of either chlorine or argon."]'::jsonb, 3, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
