insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-physics-80f6b4611c5b', 'physics-work-energy-and-power', 'physics', 'A very slow-moving positron interacts with a stationary electron. Which of the following statements correctly describes a possible outcome of this reaction and why it would occur?', '["Conservation of mass indicates that if a single new particle were created in the reaction, it must have a total mass equal to the combined masses of the electron and positron.","Conservation of charge indicates that all new particles created in the reaction would have no electric charge.","Conservation of momentum indicates that two identical gamma rays moving off in opposite directions could be created.","Conservation of energy indicates that the antimatter positron could annihilate into energy, leaving the stationary electron behind."]'::jsonb, 2, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
