insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('mmlu-physics-85b7c90f8d45', 'physics-laws-of-motion', 'physics', 'A uniform bar is lying on a flat table. Besides the gravitational and normal forces (which cancel), the bar is acted upon by two other forces, F1 and F2, which are parallel to the surface of the table. If the net force on the rod is zero, then which one of the following is true?', '["The net torque on the bar must also be zero.","The bar can accelerate translationally if F1 and F2 are not applied at the same point.","The net torque will be zero if F1 and F2 are applied at the same point.","The bar cannot accelerate translationally or rotationally."]'::jsonb, 2, '', '[]'::jsonb, '{"name":"MMLU (Center for AI Safety)","url":"https://huggingface.co/datasets/cais/mmlu","license":"MIT"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
