insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('phy-lom-0011', 'physics-laws-of-motion', 'physics', 'For a car of mass $m$ turning on a frictionless banked road of radius $r$ at speed $v$, the banking angle $\theta$ must satisfy', '["$\\tan\\theta = v^2/(rg)$","$\\tan\\theta = rg/v^2$","$\\sin\\theta = v^2 r g$","$\\tan\\theta = vg/r$"]'::jsonb, 0, 'Resolving the normal reaction with no friction: $N\sin\theta = mv^2/r$ and $N\cos\theta = mg$, giving $\tan\theta = v^2/(rg)$.', '[]'::jsonb, '{"name":"Original practice set (AI-drafted for exam-mnot.onrender.com)","license":"Original content, freely usable for this project — not sourced from any official exam paper","url":""}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
