insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('phy-lom-0013', 'physics-laws-of-motion', 'physics', 'A 0.5 kg stone tied to a 1 m string moves in a horizontal circle at 2 revolutions per second. The tension in the string (centripetal force) is approximately', '["39.5 N","79 N","158 N","197 N"]'::jsonb, 1, '$F = m\omega^2 r$, with $\omega = 2\pi n = 4\pi\ \text{rad s}^{-1}$: $F = 0.5 \times (4\pi)^2 \times 1 \approx 79\ \text{N}$.', '[]'::jsonb, '{"name":"Original practice set (AI-drafted for exam-mnot.onrender.com)","license":"Original content, freely usable for this project — not sourced from any official exam paper","url":""}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
