insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('phy-lom-0015', 'physics-laws-of-motion', 'physics', 'A 60 kg person stands in a lift accelerating upward at 2 m s$^{-2}$. Taking $g = 10\ \text{m s}^{-2}$, the apparent weight (normal reaction) is', '["600 N","660 N","720 N","780 N"]'::jsonb, 2, '$N = m(g+a) = 60(10+2) = 720\ \text{N}$.', '[]'::jsonb, '{"name":"Original practice set (AI-drafted for exam-mnot.onrender.com)","license":"Original content, freely usable for this project — not sourced from any official exam paper","url":""}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
